function mirrorSelection(axis){if(!selection.size)return;const pivot=pivotPosition(),reflection=new THREE.Matrix4().makeScale(...[0,1,2].map(i=>i===axis?-1:1)),delta=new THREE.Matrix4().makeTranslation(...pivot.toArray()).multiply(reflection).multiply(new THREE.Matrix4().makeTranslation(...pivot.toArray().map(v=>-v)));mutate(()=>{for(const o of project.objects.filter(o=>selection.has(o.id))){const m=meshMap.get(o.id);m.updateMatrix();const matrix=delta.clone().multiply(m.matrix),pos=new THREE.Vector3(),q=new THREE.Quaternion(),scale=new THREE.Vector3();matrix.decompose(pos,q,scale);o.position=pos.toArray();o.rotation=new THREE.Euler().setFromQuaternion(q,'XYZ').toArray().slice(0,3).map(v=>v*180/Math.PI);o.size=scale.toArray().map(v=>Math.abs(v));o.mirror=scale.toArray().map(v=>Math.sign(v)||1);}writeSelectionKeys();});}

function select(id,multi=false,individual=false){stopPointEdit(false);selectedGroupId=null;if(id!==primary)$('assetSearch').value='';const ids=id?(individual?[id]:connectedObjects(project,[id])):[];if(multi&&id){const remove=ids.every(x=>selection.has(x));for(const x of ids)remove?selection.delete(x):selection.add(x);primary=selection.has(id)?id:[...selection].at(-1);}else{selection=new Set(ids);primary=id;}refreshList();refreshBody();refreshKeys();refreshEnabled();if(activeTab==='structure')refreshStructure();if(activeTab==='connection')refreshConnections();updateOutlines();attachTransform();}
function fitView(){if(!project.objects.length){camera.position.set(10,9,13);orbit.target.set(0,1,0);return;}const box=new THREE.Box3();for(const [id,mesh]of meshMap){mesh.updateMatrixWorld(true);if(mesh.children.length)box.expandByObject(mesh);else{const o=project.objects.find(o=>o.id===id);for(const part of shapeParts(o)){const local=new THREE.Matrix4().compose(new THREE.Vector3().fromArray(part.c),new THREE.Quaternion().fromArray(part.q),new THREE.Vector3().fromArray(part.s));box.union(new THREE.Box3(new THREE.Vector3(-.5,-.5,-.5),new THREE.Vector3(.5,.5,.5)).applyMatrix4(mesh.matrixWorld.clone().multiply(local)));}}}for(const c of project.connections||[])for(const p of connectionEndpoints(c,new Map(project.objects.map(o=>[o.id,o]))))box.expandByPoint(new THREE.Vector3(...p));const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),d=Math.max(6,Math.max(size.x,size.y,size.z)*2);camera.far=Math.max(300,d*10);camera.updateProjectionMatrix();orbit.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(d*.8,d*.65,d));orbit.update();}
