 const group=(g,depth=0)=>{const members=groupMembers(project,g.id),all=members.length&&members.every(id=>selection.has(id)),folded=foldedGroups.has(g.id),hidden=members.every(id=>project.objects.find(o=>o.id===id)?.hidden);html+='<div class="tree-row tree-group '+(all?'selected ':'')+(hidden?'tree-hidden':'')+'" role="treeitem" aria-level="'+(depth+1)+'" aria-expanded="'+!folded+'" draggable="true" data-tree-group="'+g.id+'"><span class="tree-bar"></span><button class="tree-fold" aria-label="'+escape(g.name)+' '+(folded?'펼치기':'접기')+'" aria-expanded="'+!folded+'" data-fold="'+g.id+'">'+icon('chevron')+'</button><button class="object-row" data-group-select="'+g.id+'"><span class="obj-label"><span class="obj-name">'+escape(g.name)+'</span><span class="obj-english">Group</span></span></button>'+eye(g.id,hidden,true)+'</div>';if(folded)return;html+='<div class="tree-children" role="group">';for(const o of project.objects.filter(o=>o.group===g.id))row(o,depth+1);for(const child of (project.groups||[]).filter(x=>x.parent===g.id))group(child,depth+1);html+='</div>';};
