function addKey(){const keyTime=Math.round(time*20)/20,f=selectedField();if(f){const pose=fieldPose(f,time,quaternionFromEuler);if(mutate(()=>writeFieldKey(f,pose))){timelineSelection={kind:'field',id:f.id,prop:'key',keytime:keyTime};setFrame(keyTime);renderTimelineRows();}return;}const targets=!pointEdit&&!forceEdit?selectedObjects().filter(o=>!o.virtual):[];if(!targets.length)return toast('물체 또는 기류·흡인 마커를 선택하세요.');if(mutate(()=>{for(const o of targets){const mesh=meshMap.get(o.id),key={time:keyTime,position:mesh.position.toArray(),rotation:new THREE.Euler().setFromQuaternion(mesh.quaternion,'XYZ').toArray().slice(0,3).map(v=>v*180/Math.PI)};o.keys||=[];const old=o.keys.find(k=>k.time===keyTime);old?Object.assign(old,key):o.keys.push(key);o.keys.sort((a,b)=>a.time-b.time);o.fixed=false;}})){timelineSelection={kind:'object',id:primary,prop:'key',keytime:keyTime};setFrame(keyTime);renderTimelineRows();}}
