function tab(name){if(name!=='force'&&forceEdit)stopForceEdit();activeTab=name;for(const id of ['body','force','structure','connection']){$(id+'Tab').classList.toggle('active',id===name);$(id+'Tab').setAttribute('aria-selected',id===name);$(id+'Panel').hidden=id!==name;}if(name==='structure')refreshStructure();if(name==='connection')refreshConnections();if(name!=='body'&&pointEdit?.kind==='collider')stopPointEdit();updateOutlines();refreshCurveButton();}
