const frameQuaternion=new THREE.Quaternion();
function setFrame(t){time=Math.max(0,Math.min(t,project.duration));if(recording){const frame=time*20,lo=Math.min(recording.ticks,Math.floor(frame)),hi=Math.min(recording.ticks,lo+1),alpha=frame-lo;for(let i=0;i<recording.objects.length;i++){const a=recording.frames[lo][i],b=recording.frames[hi][i],mesh=meshMap.get(a.id);if(a===b&&mesh.position.x===a.p[0]&&mesh.position.y===a.p[1]&&mesh.position.z===a.p[2]&&mesh.quaternion.x===a.q[0]&&mesh.quaternion.y===a.q[1]&&mesh.quaternion.z===a.q[2]&&mesh.quaternion.w===a.q[3])continue;mesh.position.set(a.p[0]+(b.p[0]-a.p[0])*alpha,a.p[1]+(b.p[1]-a.p[1])*alpha,a.p[2]+(b.p[2]-a.p[2])*alpha);mesh.quaternion.fromArray(a.q).slerp(frameQuaternion.fromArray(b.q),alpha);}}else for(const o of project.objects){const mesh=meshMap.get(o.id);if(!o.virtual&&o.keys?.length){const s=sampleKeys(o,time,quaternionFromEuler);mesh.position.fromArray(s.p);mesh.quaternion.fromArray(s.q);}else{mesh.position.fromArray(o.position);mesh.quaternion.fromArray(quaternionFromEuler(o.rotation));}}refreshTimeline();updateConnections();updateExplosionParticles();updateFields();syncPoint();updateOutlines();if(activeTab==='key'&&!playing)refreshKeys();if(!playing)refreshTransformValues();updateForceArrow();if(!playing&&!dragEdit)attachTransform();}
async function bake(){if(busy||!project.objects.length)return false;playing=false;bakeStop=false;stopPointEdit(false);stopForceEdit();setBusy(true);$('stopRecord').hidden=false;$('stopRecord').disabled=false;transform.detach();status('물리 시뮬레이션 기록 중');try{recording=await simulate(project,(progress,info={})=>{const detail=progress==null?(info.time||0).toFixed(1)+'초':Math.round(progress*100)+'%';$('clipLabel').textContent='물리 계산 '+detail;status('기록 중 · '+detail+(info.warning?' · '+info.warning+' · 기록 중지로 끝내기':''));},()=>new Promise(requestAnimationFrame),{autoStop:project.autoStop!==false,shouldStop:()=>bakeStop});project.duration=recording.stopReason==='rest'?Math.max(.5,recording.duration,...(project.speedSegments||[]).map(s=>s.time+s.duration)):Math.max(project.duration,recording.duration);time=0;commit(true);setFrame(0);const reason={rest:'움직임 정지 · 자동 종료',manual:'사용자가 기록 중지',memory:'메모리 보호 · 현재 구간까지 기록',bounds:'작업 영역 이탈 · 현재 구간까지 기록',duration:'설정한 길이까지 기록'}[recording.stopReason];status(reason+' · '+recording.duration.toFixed(2)+'초');if(['memory','bounds'].includes(recording.stopReason))toast(reason+'했습니다. 물체를 줄이거나 구간을 나누어 기록하세요.');return true;}catch(e){recording=null;toast('기록 실패: '+e.message);status('기록 실패 · 장면 설정을 확인하세요');return false;}finally{$('stopRecord').hidden=true;setBusy(false);attachTransform();}}
