function refresh(){refreshTimeline.project=null;if(selectedGroupId&&!project.groups.some(g=>g.id===selectedGroupId))selectedGroupId=null;refreshEnabled();rebuildMeshes();rebuildConnections();rebuildExplosions();rebuildFields();refreshList();refreshBody();refreshEvents();refreshStructure();refreshKeys();refreshConnections();refreshTimeline();updateForceArrow();$('projectName').value=project.name;$('autoStop').checked=project.autoStop!==false;$('duration').value=project.duration;$('gravity').value=project.gravity;$('floorFriction').value=project.floorFriction;$('undo').disabled=historyIndex===0;$('redo').disabled=historyIndex===history.length-1;setFrame(time);syncPoint();}
async function undo(delta){if(busy||historyIndex+delta<0||historyIndex+delta>=history.length)return;const nextIndex=historyIndex+delta,state=clone(history[nextIndex]);if(state.gameVersion!==project.gameVersion){if(await loadProject(state,false)){historyIndex=nextIndex;refresh();}return;}historyIndex=nextIndex;project=state;selection=new Set([...selection].filter(id=>project.objects.some(o=>o.id===id)));primary=[...selection].at(-1);invalidate();autosave();refresh();}
function deleteSelection(){if(pointEdit){const {kind,id}=pointEdit;stopPointEdit(false);mutate(()=>{if(kind==='collider'){for(const o of selectedObjects()){o.customColliders=editableParts(o);o.customColliders.splice(colliderIndex,1);}}else if(kind==='field')project.fields=project.fields.filter(f=>f.id!==id);else if(kind==='connection')project.connections=project.connections.filter(c=>c.id!==id);else project.explosions=project.explosions.filter(e=>e.id!==id);});return;}mutate(()=>{project.connections=(project.connections||[]).filter(c=>!selection.has(c.a)&&!selection.has(c.b));project.objects=project.objects.filter(o=>!selection.has(o.id));project.events=project.events.filter(e=>!selection.has(e.target)&&(!e.target.startsWith('g')||groupMembers(project,e.target).length));selection.clear();primary=null;});}
function duplicate(){if(selection.size)paste(copySelection(project,[...selection]));}
function bindEditingTools(){$('selectMaterialMatches').onclick=selectSameMaterial;$('materialOnlySelect').onchange=()=>{if($('materialOnlySelect').checked&&!selection.size)toast('기준 물체를 선택한 뒤 Ctrl로 영역을 드래그하세요.');};$('foldAllGroups').onclick=()=>{const all=project.groups.every(g=>foldedGroups.has(g.id));for(const g of project.groups)all?foldedGroups.delete(g.id):foldedGroups.add(g.id);refreshList();};for(const [id,fn] of [['dockBlock',()=>openLibrary('block')],['dockItem',()=>openLibrary('item')],['dockDuplicate',duplicate],['dockGroup',toggleGroupSelection]])$(id).onclick=fn;renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0||!e.ctrlKey||busy||forceEdit||pointEdit||jointPick)return;if($('materialOnlySelect').checked&&!selected()){e.stopImmediatePropagation();toast('기준 물체를 먼저 선택하세요.');return;}boxDrag={x:e.clientX,y:e.clientY,add:e.shiftKey,materials:$('materialOnlySelect').checked&&selected()?new Set([(selected().type||'block')+'|'+selected().block+'|'+!!selected().virtual]):null};orbit.enabled=false;e.stopImmediatePropagation();$('selectionBox').hidden=false;},true);renderer.domElement.addEventListener('pointermove',e=>{if(!boxDrag)return;const rect=viewport.getBoundingClientRect(),x=Math.min(e.clientX,boxDrag.x),y=Math.min(e.clientY,boxDrag.y);Object.assign($('selectionBox').style,{left:x-rect.left+'px',top:y-rect.top+'px',width:Math.abs(e.clientX-boxDrag.x)+'px',height:Math.abs(e.clientY-boxDrag.y)+'px'});},true);renderer.domElement.addEventListener('pointerup',e=>{if(!boxDrag)return;e.stopImmediatePropagation();const left=Math.min(boxDrag.x,e.clientX),right=Math.max(boxDrag.x,e.clientX),top=Math.min(boxDrag.y,e.clientY),bottom=Math.max(boxDrag.y,e.clientY),rect=renderer.domElement.getBoundingClientRect();if(!boxDrag.add)selection.clear();for(const [id,mesh]of meshMap){const o=project.objects.find(o=>o.id===id);if(boxDrag.materials?.size&&!boxDrag.materials.has((o.type||'block')+'|'+o.block+'|'+!!o.virtual))continue;const box=new THREE.Box3().setFromObject(mesh);if(box.isEmpty()||!mesh.visible)continue;const xs=[],ys=[];for(const x of [box.min.x,box.max.x])for(const y of [box.min.y,box.max.y])for(const z of [box.min.z,box.max.z]){const p=new THREE.Vector3(x,y,z).project(camera);if(p.z>1||p.z<-1)continue;xs.push(rect.left+(p.x+1)*rect.width/2);ys.push(rect.top+(1-p.y)*rect.height/2);}if(xs.length&&Math.min(...xs)<=right&&Math.max(...xs)>=left&&Math.min(...ys)<=bottom&&Math.max(...ys)>=top)selection.add(id);}if(!boxDrag.materials?.size)selection=new Set(connectedObjects(project,[...selection]));primary=[...selection][0];selectedGroupId=null;boxDrag=null;$('selectionBox').hidden=true;orbit.enabled=true;selectAllRefresh();},true);renderer.domElement.addEventListener('pointercancel',()=>{boxDrag=null;$('selectionBox').hidden=true;orbit.enabled=true;});renderer.domElement.addEventListener('contextmenu',e=>{e.preventDefault();if(busy||forceEdit||downAt&&Math.hypot(e.clientX-downAt.x,e.clientY-downAt.y)>5)return;showContextMenu(e.clientX,e.clientY);});$('objectList').addEventListener('contextmenu',e=>{e.preventDefault();if(busy)return;const row=e.target.closest('[data-tree-object],[data-tree-group]');if(!row)return;const id=row.dataset.treeObject||row.dataset.treeGroup;if(row.dataset.treeGroup){if(selectedGroupId!==id)selectGroup(id);}else if(!selection.has(id))select(id);showContextMenu(e.clientX,e.clientY);});document.addEventListener('pointerdown',e=>{if(!e.target.closest('#contextMenu'))$('contextMenu').hidden=true;});}
function renameSelection(){const row=$('objectList').querySelector(selectedGroupId?'[data-tree-group="'+selectedGroupId+'"]':'[data-tree-object="'+primary+'"]');if(row){beginTreeRename(row);return;}if(selectedGroupId){tab('structure');const input=$('structurePanel').querySelector('[data-group="'+selectedGroupId+'"] input[type=text]');input?.focus();input?.select();}else{tab('body');$('bodyName').focus();$('bodyName').select();}}
function selectSameMaterial(){const seed=selected();if(!seed){toast('먼저 기준 물체를 하나 선택하세요.');return;}const keys=new Set([(seed.type||'block')+'|'+seed.block+'|'+!!seed.virtual]);selection=new Set(project.objects.filter(o=>!o.hidden&&keys.has((o.type||'block')+'|'+o.block+'|'+!!o.virtual)).map(o=>o.id));primary=[...selection][0];selectedGroupId=null;selectAllRefresh();}
