function rebuildFields(){for(const m of fieldMarkers.values()){scene.remove(m);disposeMarker(m);}fieldMarkers.clear();for(const f of project.fields||[]){const m=createMarker(f.kind,f.id);scene.add(m);fieldMarkers.set(f.id,m);}updateFields();}
function updateFields(){for(const f of project.fields||[]){const m=fieldMarkers.get(f.id);if(!m)continue;const pose=fieldPose(f,time,quaternionFromEuler);m.position.fromArray(pose.p);m.quaternion.fromArray(pose.q);setMarkerSize(m,pose.size);m.visible=!playing;m.traverse(child=>{if(child.material)child.material.opacity=time>=f.time&&(f.continuous||time<=f.time+f.duration)?.85:.35;});}}
function addVirtual(){openLibrary('block',true);}
