function pinSnapPoints(id){const root=meshMap.get(id);if(!root)return [];root.updateMatrixWorld(true);const result=[],seen=new Set(),add=(p,label)=>{const key=p.toArray().map(v=>v.toFixed(7)).join(',');if(!seen.has(key)){seen.add(key);result.push({p:p.toArray(),label});}};add(root.getWorldPosition(new THREE.Vector3()),'물체 중심');root.traverse(mesh=>{if(!mesh.isMesh||!mesh.geometry)return;mesh.geometry.computeBoundingBox();const b=mesh.geometry.boundingBox;if(!b)return;const corners=[];for(let x=0;x<2;x++)for(let y=0;y<2;y++)for(let z=0;z<2;z++)corners.push(new THREE.Vector3(x?b.max.x:b.min.x,y?b.max.y:b.min.y,z?b.max.z:b.min.z).applyMatrix4(mesh.matrixWorld));for(const p of corners)add(p,'꼭짓점');for(let i=0;i<8;i++)for(const bit of [1,2,4])if(!(i&bit))add(corners[i].clone().add(corners[i|bit]).multiplyScalar(.5),'모서리 중앙');});return result;}
