function timelineTarget(kind,id){return kind==='speed'?project.speedSegments?.find(s=>s.id===id):kind==='event'?project.events.find(e=>e.id===id):kind==='explosion'?project.explosions?.find(e=>e.id===id):kind==='field'?project.fields?.find(e=>e.id===id):project.objects.find(e=>e.id===id);}
