function chooseBuildingMode(data){$('buildingReal').disabled=$('buildingVirtual').disabled=false;$('buildingModeSummary').textContent=data.name+' · '+data.placements.length+'개 블록';return new Promise(resolve=>{const dialog=$('buildingModeDialog');let result=null;$('buildingReal').onclick=()=>{result=false;dialog.close();};$('buildingVirtual').onclick=()=>{result=true;dialog.close();};dialog.addEventListener('close',()=>resolve(result),{once:true});dialog.showModal();});}
function renderShapePreviews(){
 for(const button of $('shapesDialog').querySelectorAll('[data-shape]')){
  const canvas=button.querySelector('canvas'),ctx=canvas.getContext('2d');
  const preview=shapePreview(button.dataset.shape,+$('shapeResolution').value,canvas.width,canvas.height);
  ctx.clearRect(0,0,canvas.width,canvas.height);
  for(const {points,shade}of preview.faces){
   ctx.fillStyle='rgb('+shade+','+(shade+3)+','+(shade+6)+')';ctx.beginPath();
   points.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](...p));ctx.closePath();ctx.fill();
  }
  ctx.lineWidth=.65;ctx.strokeStyle='rgba(65,73,85,.65)';ctx.beginPath();
  for(const [a,b]of preview.edges){ctx.moveTo(...a);ctx.lineTo(...b);}ctx.stroke();
  button.title=preview.triangleCount+'개 삼각형 면';
 }
}

